#!/usr/bin/env python3
import types,sys,sqlite3,json
pb=types.ModuleType("pseudobulk_contract")
exec(compile(bytes.fromhex(""),"bundled-pseudobulk-contract","exec"),pb.__dict__)
bc=types.ModuleType("research_b_counts");bc.pb=pb
previous_bc=sys.modules.get("research_b_counts");sys.modules["research_b_counts"]=bc
bi=types.ModuleType("b_donor_inputs")
try:
    exec(compile(bytes.fromhex(""),"bundled-b-donor-inputs","exec"),bi.__dict__)
finally:
    if previous_bc is None:sys.modules.pop("research_b_counts",None)
    else:sys.modules["research_b_counts"]=previous_bc

import os
from pathlib import Path
import tempfile

COUNT_NAMES = ['counts.mtx','features.tsv','feature-qc.tsv','columns.tsv','cell-qc.tsv','audit.json']
OUTPUT_NAMES = ['method-template.json','genes.tsv','samples.tsv','decisions.tsv','provenance.json']

def run():
    inputs = [Path(os.environ['AUTONOMICS_INPUT'+str(i)]) for i in range(11)]
    outputs = [Path(os.environ['AUTONOMICS_OUTPUT'+str(i)]) for i in range(5)]
    pb.require([p.name for p in outputs] == OUTPUT_NAMES and
        len({p.parent.absolute() for p in outputs}) == 1,
        'complete declared donor output set in one private directory required')
    parent = outputs[0].parent.absolute()
    pb.require(all(p.is_absolute() and '..' not in p.parts for p in outputs) and parent != Path('/'),
        'private absolute output paths without parent traversal required')
    pb.require(not any(os.path.lexists(p) for p in outputs), 'output exists; refusing overwrite')
    pb.require(not any(p.is_symlink() for p in [parent,*parent.parents]), 'symlink output ancestor')
    parent.mkdir(parents=True,exist_ok=True)
    bundle = parent / '.b-donor-inputs-complete'
    pb.require(not os.path.lexists(bundle), 'complete donor bundle already exists')
    # Disk-backed cell QC belongs in the private output workspace, not /tmp's
    # smaller tmpfs. This process owns this scratch directory exclusively.
    previous_tempdir = tempfile.tempdir
    with tempfile.TemporaryDirectory(prefix='.b-donor-scratch-',dir=parent) as scratch:
        tempfile.tempdir = scratch
        try:
            payloads = bi.prepare(pb.bounded(inputs[0]),dict(zip(COUNT_NAMES,inputs[1:7])),
                *[pb.bounded(p) for p in inputs[7:11]])
            bi.publish(bundle,payloads)
        finally:
            tempfile.tempdir = previous_tempdir
    # No-clobber hard links expose only the complete validated bundle. On a
    # link failure leave diagnostic workspace intact; the engine must reject
    # publication when the process exits nonzero. Never delete a foreign port.
    for target in outputs:
        os.link(bundle/target.name,target)
    print(json.dumps({'scope':'SOURCE_BOUND_MODEL_INPUT_PREPARATION_NOT_METHOD_OR_G0',
        'formal_authorized':False}))

if __name__ == '__main__':
    try:
        run()
    except (ValueError,KeyError,OSError,sqlite3.Error,UnicodeError,pb.csv.Error) as error:
        print('BLOCKED: '+str(error),file=sys.stderr)
        raise SystemExit(2)
